import itertools
import math

def max_polygon_area(segments):
    n = len(segments)
    if n < 3:
        return 0.0

    def is_valid_polygon(sides):
        sides.sort()
        return sum(sides[:-1]) > sides[-1]

    def polygon_area(sides):
        # Using Brahmagupta's formula for cyclic quadrilaterals
        if len(sides) == 4:
            a, b, c, d = sides
            s = (a + b + c + d) / 2
            return math.sqrt((s - a) * (s - b) * (s - c) * (s - d))

        # For triangles, using Heron's formula
        if len(sides) == 3:
            a, b, c = sides
            s = (a + b + c) / 2
            return math.sqrt(s * (s - a) * (s - b) * (s - c))

        return 0.0

    max_area = 0.0
    for r in range(3, n + 1):
        for combination in itertools.combinations(segments, r):
            if is_valid_polygon(combination):
                area = polygon_area(combination)
                if area > max_area:
                    max_area = area

    return max_area

# Read input
