import random
import math
import sys

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def perimeter(points):
    n = len(points)
    return sum(distance(points[i], points[(i + 1) % n]) for i in range(n))

def area(points):
    n = len(points)
    return abs(sum(points[i][0] * points[(i + 1) % n][1] - points[(i + 1) % n][0] * points[i][1] for i in range(n))) / 2.0

def is_valid_polygon(points):
    n = len(points)
    if n < 3:
        return False
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if area([points[i], points[j], points[k]]) == 0:
                    return False
    return True

def simulated_annealing(segments, max_iterations=10000, initial_temp=1000, cooling_rate=0.99):
    n = len(segments)
    best_area = 0
    best_points = []

    def random_polygon():
        points = [(random.uniform(0, 100), random.uniform(0, 100)) for _ in range(n)]
        while not is_valid_polygon(points):
            points = [(random.uniform(0, 100), random.uniform(0, 100)) for _ in range(n)]
        return points

    current_points = random_polygon()
    current_area = area(current_points)

    for iteration in range(max_iterations):
        temp = initial_temp * (cooling_rate ** iteration)
        new_points = [point[:] for point in current_points]
        i, j = random.sample(range(n), 2)
        new_points[i], new_points[j] = new_points[j], new_points[i]

        if is_valid_polygon(new_points):
            new_area = area(new_points)
            delta = new_area - current_area
            if delta > 0 or random.random() < math.exp(delta / temp):
                current_points = new_points
                current_area = new_area

            if current_area > best_area:
                best_area = current_area
                best_points = current_points

    return best_area

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    segments = list(map(int, data[1:]))

    max_area = simulated_annealing(segments)
    print(f"{max_area:.3f}")

if __name__ == "__main__":
    main()
